"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[85],{1442:(e,a,o)=>{o.d(a,{cn:()=>i});function i(...e){return e.filter(Boolean).join(" ")}},2381:(e,a,o)=>{o.d(a,{kL:()=>r,mc:()=>i});let i=[{slug:"arquitectura",n:"01",school:"Forma y C\xe1lculo",title:"Arquitectura",degree:"Arquitecto/a",years:6,jornada:"Diurna",cupos:36,arancel:648e4,image:"/images/taller.jpg",alt:"Taller de arquitectura: maquetas blancas, papel de croquis y luz norte sobre mesas de raul\xed",lead:"Seis a\xf1os de taller. El edificio se piensa desde el patio, no desde el render.",body:"En ETER la arquitectura no se ense\xf1a como un cat\xe1logo de estilos. Se ense\xf1a como una conversaci\xf3n con el sitio: la pendiente, el viento, el agua de riego, la sombra de un quillay a las cuatro de la tarde. El primer a\xf1o no hay software. Hay l\xe1piz, maqueta y un predio que se camina.",forWhom:"Quien quiere construir con rigor y no con moda. Quien acepta que el taller dura hasta tarde y que una maqueta se desarma si la idea no carga.",plan:[{year:"1–2",items:"Sitio, dibujo, estructura, historia de la forma en Chile y el Pac\xedfico."},{year:"3–4",items:"Taller de vivienda, de campus, de paisaje. Hormig\xf3n, madera, agua."},{year:"5–6",items:"T\xedtulo: un predio real, un encargo escrito, una defensa p\xfablica."}],weights:[{label:"NEM",value:"20%"},{label:"Ranking",value:"20%"},{label:"Comp. Lectora",value:"25%"},{label:"Comp. Matem\xe1tica 1",value:"25%"},{label:"Historia y Cs. Sociales",value:"10%"}],faculty:"camila-rojas",portfolio:!0,outcomes:["Oficina propia o asociada","Obra p\xfablica y paisaje","Docencia e investigaci\xf3n de forma"]},{slug:"paisaje",n:"02",school:"Tierra y Atm\xf3sfera",title:"Arquitectura del Paisaje",degree:"Arquitecto/a del Paisaje",years:5,jornada:"Diurna",cupos:24,arancel:592e4,image:"/images/patio.jpg",alt:"Claustro del campus: un array\xe1n en un estanque raso, columnata de hormig\xf3n claro",lead:"El paisaje no es jard\xedn. Es territorio, agua, sombra y tiempo.",body:"Chile se ense\xf1a mal si se ense\xf1a como postal. Aqu\xed el paisaje es la acequia, el talud, el incendio, la quebrada que se seca en marzo. Cinco a\xf1os para leer un predio y devolverle un orden que no lo humille.",forWhom:"Quien viene de la biolog\xeda, de la arquitectura o de la tierra, y no quiere elegir entre ellas.",plan:[{year:"1–2",items:"Bot\xe1nica de Chile central, hidrolog\xeda, dibujo de sitio, suelos."},{year:"3–4",items:"Taller de quebrada, de campus, de borde urbano. Restauraci\xf3n."},{year:"5",items:"T\xedtulo sobre un predio de la precordillera o del valle."}],weights:[{label:"NEM",value:"20%"},{label:"Ranking",value:"20%"},{label:"Comp. Lectora",value:"20%"},{label:"Comp. Matem\xe1tica 1",value:"20%"},{label:"Ciencias",value:"20%"}],faculty:"elisa-montes",portfolio:!0,outcomes:["Parques y bordes urbanos","Restauraci\xf3n de quebradas","Consultor\xeda de territorio"]},{slug:"diseno",n:"03",school:"Forma y C\xe1lculo",title:"Dise\xf1o",degree:"Dise\xf1ador/a",years:4,jornada:"Diurna",cupos:28,arancel:574e4,image:"/images/taller.jpg",alt:"Mesas de taller con rollos de papel y maquetas de patio, luz de ventana",lead:"Objetos, signos y sistemas. Nada de ‘creatividad’ como adjetivo vac\xedo.",body:"El dise\xf1o en ETER parte del uso y del material. Tipograf\xeda, objeto, interfaz y espacio se ense\xf1an en el mismo taller: si no se puede hacer a mano, no se digitaliza. El portafolio de egreso es una pieza, no un PDF de mockups.",forWhom:"Quien quiere oficio, no moodboard. Quien acepta que el primer a\xf1o se dibuja y se recorta antes de abrir un software.",plan:[{year:"1–2",items:"Dibujo, tipograf\xeda, material, color, historia de la forma."},{year:"3",items:"Taller de objeto, de edici\xf3n, de interfaz. Encargo real."},{year:"4",items:"T\xedtulo: una pieza producida, no ilustrada."}],weights:[{label:"NEM",value:"20%"},{label:"Ranking",value:"20%"},{label:"Comp. Lectora",value:"30%"},{label:"Comp. Matem\xe1tica 1",value:"20%"},{label:"Historia y Cs. Sociales",value:"10%"}],faculty:"camila-rojas",portfolio:!0,outcomes:["Estudios de dise\xf1o","Edici\xf3n y tipograf\xeda","Producto e interfaz"]},{slug:"clima",n:"04",school:"Tierra y Atm\xf3sfera",title:"Ingenier\xeda en Ciencias del Clima",degree:"Ingeniero/a en Ciencias del Clima",years:5,jornada:"Diurna",cupos:32,arancel:615e4,image:"/images/laboratorio.jpg",alt:"Laboratorio de atm\xf3sfera con instrumentos de vidrio y ventana abierta a los Andes",lead:"Medir, modelar y escribir el aire de Chile. No hay ‘conciencia ambiental’ sin n\xfamero.",body:"La precordillera es un instrumento. Cinco a\xf1os de f\xedsica, c\xe1lculo, observaci\xf3n y campo. El laboratorio mira al macizo porque el dato se toma aqu\xed, no se descarga de un paper extranjero y se traduce.",forWhom:"Quien quiere ciencia dura con sitio. Quien no busca un slogan verde sino una estaci\xf3n, una serie y un modelo que se defienda.",plan:[{year:"1–2",items:"C\xe1lculo, f\xedsica, qu\xedmica de la atm\xf3sfera, programaci\xf3n cient\xedfica."},{year:"3–4",items:"Observaci\xf3n, modelos, hidrolog\xeda andina, campo en El Array\xe1n."},{year:"5",items:"Memoria: una serie propia, un modelo, una defensa."}],weights:[{label:"NEM",value:"15%"},{label:"Ranking",value:"15%"},{label:"Comp. Lectora",value:"15%"},{label:"Comp. Matem\xe1tica 1",value:"30%"},{label:"Ciencias",value:"25%"}],faculty:"pedro-alarcon",portfolio:!1,outcomes:["Servicios clim\xe1ticos","Investigaci\xf3n y estaciones","Pol\xedtica p\xfablica con dato"]},{slug:"territorio",n:"05",school:"Tierra y Atm\xf3sfera",title:"Geograf\xeda y Territorio",degree:"Ge\xf3grafo/a",years:4,jornada:"Diurna",cupos:28,arancel:521e4,image:"/images/cielo.jpg",alt:"Cordillera de los Andes al amanecer, vista desde un pretil de hormig\xf3n en El Array\xe1n",lead:"Leer el mapa como se lee un texto: con paciencia y sin adorno.",body:"Chile se administra mal cuando se administra desde el escritorio de Santiago centro. Aqu\xed el territorio se camina: quebrada, loteo, riego, incendio, borde. SIG, cartograf\xeda y escritura de informe son el mismo oficio.",forWhom:"Quien quiere el dato espacial y la frase precisa. Quien no confunde geograf\xeda con turismo.",plan:[{year:"1–2",items:"Cartograf\xeda, f\xedsica de la tierra, SIG, escritura de informe."},{year:"3",items:"Taller de cuenca, de ciudad, de riesgo. Campo."},{year:"4",items:"Memoria sobre un territorio nominado, no gen\xe9rico."}],weights:[{label:"NEM",value:"20%"},{label:"Ranking",value:"20%"},{label:"Comp. Lectora",value:"25%"},{label:"Comp. Matem\xe1tica 1",value:"15%"},{label:"Historia y Cs. Sociales",value:"20%"}],faculty:"elisa-montes",portfolio:!1,outcomes:["Planificaci\xf3n territorial","Riesgo y cuenca","Cartograf\xeda e informe p\xfablico"]},{slug:"computacion",n:"06",school:"Forma y C\xe1lculo",title:"Ingenier\xeda Civil en Computaci\xf3n",degree:"Ingeniero/a Civil en Computaci\xf3n",years:6,jornada:"Diurna",cupos:40,arancel:628e4,image:"/images/computacion.jpg",alt:"Sala de computaci\xf3n vac\xeda, pantallas apagadas y ventana a la precordillera",lead:"Algoritmo, sistema y \xe9tica del dato. El laboratorio tiene vista al macizo a prop\xf3sito.",body:"No formamos ‘el talento del futuro’. Formamos gente que escribe c\xf3digo que se puede leer, sistemas que se pueden auditar y modelos que declaran su sesgo. Seis a\xf1os, matem\xe1tica seria, talleres de doce. El \xfaltimo a\xf1o es un sistema en producci\xf3n, no un demo.",forWhom:"Quien quiere rigor, no bootcamp. Quien acepta que el primer a\xf1o es matem\xe1tica y que el software se defiende como se defiende un teorema.",plan:[{year:"1–2",items:"C\xe1lculo, \xe1lgebra, estructuras de datos, sistemas."},{year:"3–4",items:"Redes, compiladores, aprendizaje de m\xe1quinas, taller de producto."},{year:"5–6",items:"T\xedtulo: un sistema en uso, con bit\xe1cora y defensa."}],weights:[{label:"NEM",value:"15%"},{label:"Ranking",value:"15%"},{label:"Comp. Lectora",value:"15%"},{label:"Comp. Matem\xe1tica 1",value:"35%"},{label:"Ciencias",value:"20%"}],faculty:"ignacio-beltran",portfolio:!1,outcomes:["Sistemas e infraestructura","Investigaci\xf3n aplicada","Producto con responsabilidad de dato"]},{slug:"letras",n:"07",school:"Palabra y Ciudad",title:"Literatura y Edici\xf3n",degree:"Licenciado/a en Literatura y Edici\xf3n",years:4,jornada:"Diurna",cupos:24,arancel:489e4,image:"/images/biblioteca.jpg",alt:"Sala de lectura de la biblioteca, mesas de roble claro y ventanal alto hacia la monta\xf1a",lead:"Leer en serio. Editar en serio. El libro como oficio, no como contenido.",body:"Cuatro a\xf1os de lectura, filolog\xeda, traducci\xf3n y taller de edici\xf3n. La biblioteca de ETER no es un living: es una sala de trabajo con luz norte. Se egresa con un libro hecho — no con un ensayo sobre ‘el futuro de la lectura’.",forWhom:"Quien lee m\xe1s de lo que publica. Quien quiere el oficio del original, de la prueba y de la caja.",plan:[{year:"1–2",items:"Literatura chilena y del Pac\xedfico, lat\xedn o griego, teor\xeda, escritura."},{year:"3",items:"Taller de edici\xf3n, traducci\xf3n, archivo. Encargo con un sello."},{year:"4",items:"T\xedtulo: un libro editado de punta a punta."}],weights:[{label:"NEM",value:"20%"},{label:"Ranking",value:"20%"},{label:"Comp. Lectora",value:"40%"},{label:"Comp. Matem\xe1tica 1",value:"10%"},{label:"Historia y Cs. Sociales",value:"10%"}],faculty:"soledad-munoz",portfolio:!1,outcomes:["Editoriales y archivos","Traducci\xf3n","Docencia e investigaci\xf3n literaria"]},{slug:"gobierno",n:"08",school:"Palabra y Ciudad",title:"Ciencias Pol\xedticas y Gobierno",degree:"Cientista Pol\xedtico/a",years:4,jornada:"Diurna",cupos:28,arancel:546e4,image:"/images/aula.jpg",alt:"Sala de seminario con mesa ovalada de madera y ventanal al macizo andino",lead:"Gobernar es una forma de mirar. Se ense\xf1a en seminario, no en auditorio.",body:"Instituciones chilenas, territorio, hacienda y escritura p\xfablica. El seminario es de doce: se habla y se escribe, no se toma apunte de una diapositiva. El egreso es un informe que un municipio o un ministerio podr\xeda usar — no un paper que nadie lee.",forWhom:"Quien quiere el Estado por dentro, no el comentario de Twitter. Quien acepta leer ley y presupuesto.",plan:[{year:"1–2",items:"Historia institucional de Chile, teor\xeda, econom\xeda, escritura p\xfablica."},{year:"3",items:"Seminario de hacienda, de ciudad, de territorio. Pasant\xeda."},{year:"4",items:"Memoria: un problema nominado, un informe, una defensa."}],weights:[{label:"NEM",value:"20%"},{label:"Ranking",value:"20%"},{label:"Comp. Lectora",value:"30%"},{label:"Comp. Matem\xe1tica 1",value:"15%"},{label:"Historia y Cs. Sociales",value:"15%"}],faculty:"magdalena-vidal",portfolio:!1,outcomes:["Estado y municipios","Think tanks y archivo","Asesor\xeda territorial"]}],r=[{q:"\xbfETER es universidad o instituto?",a:"Instituto universitario de sede \xfanica. Ocho carreras de pregrado y tres mag\xedster. No abrimos una novena para parecer m\xe1s grandes. El t\xedtulo profesional lo otorga la Fundaci\xf3n Instituto ETER."},{q:"\xbfC\xf3mo se entra? \xbfHay que dar la PAES?",a:"S\xed. Admisi\xf3n 2027 usa PAES 2026, NEM y ranking. Arquitectura, paisaje y dise\xf1o piden adem\xe1s un portafolio de diez l\xe1minas. Todas las carreras incluyen una entrevista de 25 minutos en el campus. Las ponderaciones est\xe1n publicadas en cada carrera."},{q:"\xbfCu\xe1nto cuesta? \xbfHay gratuidad o CAE?",a:"El arancel anual va de $4.890.000 (Letras) a $6.480.000 (Arquitectura). Matr\xedcula $320.000. Publicamos la cifra, no un ‘desde’. Informamos las v\xedas de financiamiento vigentes en Chile; no prometemos beneficios que no administramos. La Beca Altura y la Beca Territorio s\xed son nuestras."},{q:"\xbfHay residencia?",a:"Cuarenta y ocho camas en el predio, con prioridad para quien viene de fuera de la Regi\xf3n Metropolitana y para la Beca Territorio. El cupo se asigna con la matr\xedcula, no se vende por separado como un hotel."},{q:"\xbfEs jornada diurna? \xbfHay vespertino?",a:"Todas las carreras son diurnas, en El Array\xe1n. No hay vespertino ni online. El taller pide presencia. Si el oficio no cabe en esa forma, no es este instituto."},{q:"\xbfPuedo visitar el campus?",a:"S\xed. S\xe1bados de marzo a enero, 9:00 a 13:00, con inscripci\xf3n previa. El recorrido dura una hora: claustro, biblioteca, un taller, el seminario. Lo gu\xeda un estudiante, no un vendedor."}]},5985:(e,a,o)=>{o.r(a),o.d(a,{Reveal:()=>n});var i=o(5155),r=o(2115),l=o(1442);function n({children:e,className:a,delay:o=0}){let s=(0,r.useRef)(null);return(0,r.useEffect)(()=>{let e=s.current;if(!e)return;if(window.matchMedia("(prefers-reduced-motion: reduce)").matches)return void e.classList.add("is-visible");let a=new IntersectionObserver(([o])=>{o.isIntersecting&&(e.classList.add("is-visible"),a.disconnect())},{threshold:.16,rootMargin:"0px 0px -8% 0px"});return a.observe(e),()=>a.disconnect()},[]),(0,i.jsx)("div",{ref:s,className:(0,l.cn)("reveal",a),style:{transitionDelay:`${o}ms`},children:e})}}}]);